#include <stdio.h>

enum Kind { IS_INT, IS_DOUBLE };

struct Value {
    enum Kind kind;
    union {
        int i;
        double d;
    } num;
};

int main(void) {
    int k;
    int n;
    struct Value v;

    if (scanf("%d", &k) != 1) {
        return 1;
    }
    if (scanf("%d", &n) != 1) {
        return 1;
    }

    v.kind = (enum Kind)k;

    if (v.kind == IS_INT) {
        v.num.i = n;
        printf("整数 %d\n", v.num.i);
    } else {
        v.num.d = n * 1.5;
        printf("小数 %.1f\n", v.num.d);
    }
    return 0;
}
